var ConfigDateForm = {
  toFormatDate(date) {
    return formatDate(date, "dd MMMM yyyy", "fr_FR");
  },
  now() {
    return formatDate(/* @__PURE__ */ new Date(), "dd MMMM yyyy", "fr_FR");
  },
  oldDate(date2) {
    var diff = (new Date(date2).getTime() - (/* @__PURE__ */ new Date()).getTime()) / 1e3;
    diff /= 60 * 60 * 24;
    return Math.abs(Math.round(diff / 365.25));
  },
  closingDate(date2) {
    const d = new Date(date2);
    d.setDate(d.getDate() + 55 * 365);
    return d;
  },
  splitGrade(grade, index2) {
    if (grade != void 0 || grade != null) {
      var splitted = grade.split("-");
      if (splitted?.length > 0) {
        if (splitted[index2] !== void 0) {
          return splitted[index2];
        } else {
          return ".....";
        }
      } else {
        return ".....";
      }
    } else {
      return ".....";
    }
  }
};
